import { unstable_cache } from 'next/cache'

export type Post = {
  id: number
  title: string
  content: string
  createdAt: number
}

const posts: Post[] = [
  {
    id: 1,
    title: 'Welcome to the blog',
    content: 'This is the first post. Create a new one below!',
    createdAt: 0,
  },
]

export const getPosts = unstable_cache(
  async () => {
    return posts
  },
  ['posts'],
  {
    tags: ['posts'],
    revalidate: false,
  }
)

export function addPost(input: { title: string; content: string }): Post {
  const nextId = posts.length > 0 ? Math.max(...posts.map((p) => p.id)) + 1 : 1
  const post: Post = {
    id: nextId,
    title: input.title,
    content: input.content,
    createdAt: Date.now(),
  }
  posts.push(post)
  return post
}

